-- SUPERSEDED by 008_replace_sample_profiles.sql (new sample set). Safe to run by accident:
-- it skips rows that 008 wrote.
--
-- Give the 20 sample profiles the form's checkbox/select answers (availability, audiences,
-- speaking types, expertise, familiarity grid, languages...) so the speaker search has
-- something to filter on. The samples only had the six free-text answers before.
-- Run in Supabase SQL Editor after 005_speaker_search.sql. Safe to re-run.
-- Touches only sample-XX@example.com rows. The values come from data/sample_profiles.json
-- ("speaker_answers"), so `load-samples` sends the same answers and stays a no-op.
--
--   * Sample row already loaded: the answers are merged into raw_answers. Its tags,
--     status and revision are left alone, so nothing is re-tagged or re-billed.
--   * Sample row missing: it is inserted as completed with the PDF's expected tags,
--     marked model = 'expected-tags (no LLM call)'. To replace those with real LLM tags,
--     run block 4 of 004_samples_and_search.sql, then the worker.
--
-- It is ONE statement (no temporary table), because the Supabase SQL Editor may not keep
-- a temporary table between statements. One statement also means all-or-nothing.

with sample_speaker_answers (sample_id, email, full_name, speaker, answers, expected) as (
  values
  ('01-amara', 'sample-01@example.com', 'Amara Okafor', '{"participation_years": "2021", "current_location": "Lagos, Nigeria", "origin_location": "Enugu, Nigeria", "languages": "English, Yoruba, Igbo", "timezone": "UTC+1", "speaking_types": ["Not Interested"], "audiences": ["Students"], "expertise_areas": ["Agriculture & Food Systems"], "topic_familiarity": {}, "opportunities": ["Internships", "Mentoring", "Volunteering"], "interview_experience": "No, and I''d like training/support before starting", "regions": "Open to learning about new regions", "availability": "Interested but uncertain timing - keep me posted"}'::jsonb, '{"current_role": "CS student, University of Lagos", "project": "An app that lets small farmers photograph a diseased crop and get treatment advice, using an AI image model we trained ourselves.", "since_technovation": "I started a CS degree and I''m building a local crop-disease dataset with classmates.", "interests": "Machine learning for farming, getting more girls into STEM, and help landing my first job and polishing my CV.", "skills": "I code mostly in Python, I''ve built Android apps, I train image classifiers, and I''m good at breaking down messy problems.", "story_angles": "I learned to build tech in Lagos, far from Silicon Valley, and I trained my first AI model at 16.", "full_name": "Amara Okafor", "email": "sample-01@example.com", "_sample_id": "01-amara"}'::jsonb, '{"industry": ["Student"], "career_stage": ["Student"], "project_built_with": ["AI/Machine Learning", "Mobile App"], "project_approach": ["Social Impact"], "interests": ["AI/Machine Learning", "AgTech", "Women in STEM", "Job Searching", "Resume Building"], "skills": ["Python", "Mobile/App Development", "AI/Machine Learning", "Problem Solving"], "story_angles": ["Building Outside Major Tech Hubs", "Starting Young (built or founded as a teen)"], "project_domain": ["Agriculture & Food Systems"]}'::jsonb),
