merged as (
  update public.alumni_intake_responses r
  set raw_answers = r.raw_answers || s.speaker
  from sample_speaker_answers s
  where r.email = s.email
    and r.raw_answers is distinct from r.raw_answers || s.speaker
  and r.taxonomy_version is distinct from 'sample-profiles-v2'
  returning r.email
)
insert into public.alumni_intake_responses
  (email, full_name, raw_answers, source, source_response_id, submitted_at,
   tagging_status, tags, evidence, model, taxonomy_version, tagged_at)
select s.email, s.full_name, s.answers || s.speaker, 'sample', 'sample-' || s.sample_id, now(),
  'completed', s.expected, '{}'::jsonb, 'expected-tags (no LLM call)', 'pdf-expected', now()
from sample_speaker_answers s
where not exists (select 1 from public.alumni_intake_responses r where r.email = s.email);

-- Check: 20 sample rows, each with an availability answer.
select count(*) as samples,
       count(*) filter (where raw_answers ? 'availability') as with_speaker_answers,
       count(*) filter (where tagging_status = 'completed') as tagged
from public.alumni_intake_responses
where email like 'sample-%@example.com';
